import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { Employee, Project, Supervisor } from '../types';
import { User } from '../types';

interface SettingsPageProps {
  user: User | null;
}

export function SettingsPage({ user }: SettingsPageProps) {
  const isAdmin = user?.role === 'admin';
  const [tab, setTab] = useState<'employees' | 'projects' | 'supervisors'>('employees');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [supervisors, setSupervisors] = useState<Supervisor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  // Employee form
  const [newEmployee, setNewEmployee] = useState({ name: '', hourly_rate: '', position: '', supervisor_id: '' });
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);

  // Project form
  const [newProject, setNewProject] = useState({ name: '', labor_budget: '', overhead_percentage: '20' });
  const [editingProject, setEditingProject] = useState<Project | null>(null);

  // Supervisor form
  const [newSupervisor, setNewSupervisor] = useState({ email: '', password: '', name: '' });
  const [editingSupervisor, setEditingSupervisor] = useState<Supervisor | null>(null);
  const [editSupForm, setEditSupForm] = useState({ email: '', name: '', password: '' });

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      setError(null);
      const calls: Promise<any>[] = [api.getEmployees(), api.getProjects()];
      if (isAdmin) calls.push(api.getSupervisors());
      const results = await Promise.all(calls);
      setEmployees(results[0]);
      setProjects(results[1]);
      if (isAdmin) setSupervisors(results[2]);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load settings');
    } finally {
      setLoading(false);
    }
  }

  // --- Employee handlers ---
  async function handleAddEmployee(e: React.FormEvent) {
    e.preventDefault();
    if (!newEmployee.name || !newEmployee.hourly_rate) {
      alert('Name and hourly rate required');
      return;
    }
    try {
      setSaving(true);
      setError(null);
      const supId = isAdmin && newEmployee.supervisor_id ? parseInt(newEmployee.supervisor_id) : undefined;
      await api.createEmployee(newEmployee.name, parseFloat(newEmployee.hourly_rate), newEmployee.position, supId);
      setNewEmployee({ name: '', hourly_rate: '', position: '', supervisor_id: '' });
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create employee');
    } finally {
      setSaving(false);
    }
  }

  async function handleUpdateEmployee(e: React.FormEvent) {
    e.preventDefault();
    if (!editingEmployee) return;
    try {
      setSaving(true);
      setError(null);
      const data: any = {
        name: editingEmployee.name,
        hourly_rate: editingEmployee.hourly_rate,
        position: editingEmployee.position,
      };
      if (isAdmin) data.supervisor_id = editingEmployee.supervisor_id;
      await api.updateEmployee(editingEmployee.id, data);
      setEditingEmployee(null);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to update employee');
    } finally {
      setSaving(false);
    }
  }

  async function handleDeleteEmployee(id: number) {
    if (!window.confirm('Are you sure?')) return;
    try {
      setError(null);
      await api.deleteEmployee(id);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to delete employee');
    }
  }

  // --- Project handlers ---
  async function handleAddProject(e: React.FormEvent) {
    e.preventDefault();
    if (!newProject.name || !newProject.labor_budget) {
      alert('Name and labor budget required');
      return;
    }
    try {
      setSaving(true);
      setError(null);
      await api.createProject(newProject.name, parseFloat(newProject.labor_budget), parseFloat(newProject.overhead_percentage));
      setNewProject({ name: '', labor_budget: '', overhead_percentage: '20' });
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create project');
    } finally {
      setSaving(false);
    }
  }

  async function handleUpdateProject(e: React.FormEvent) {
    e.preventDefault();
    if (!editingProject) return;
    try {
      setSaving(true);
      setError(null);
      await api.updateProject(editingProject.id, {
        name: editingProject.name,
        labor_budget: editingProject.labor_budget,
        overhead_percentage: editingProject.overhead_percentage,
        status: editingProject.status,
      });
      setEditingProject(null);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to update project');
    } finally {
      setSaving(false);
    }
  }

  // --- Supervisor handlers ---
  async function handleAddSupervisor(e: React.FormEvent) {
    e.preventDefault();
    if (!newSupervisor.email || !newSupervisor.password) {
      alert('Email and password required');
      return;
    }
    try {
      setSaving(true);
      setError(null);
      await api.createSupervisor(newSupervisor);
      setNewSupervisor({ email: '', password: '', name: '' });
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create supervisor');
    } finally {
      setSaving(false);
    }
  }

  async function handleUpdateSupervisor(e: React.FormEvent) {
    e.preventDefault();
    if (!editingSupervisor) return;
    try {
      setSaving(true);
      setError(null);
      const data: any = { email: editSupForm.email, name: editSupForm.name };
      if (editSupForm.password) data.password = editSupForm.password;
      await api.updateSupervisor(editingSupervisor.id, data);
      setEditingSupervisor(null);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to update supervisor');
    } finally {
      setSaving(false);
    }
  }

  async function handleToggleSupervisorActive(id: number) {
    try {
      setError(null);
      await api.toggleSupervisorActive(id);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to toggle supervisor');
    }
  }

  if (loading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <p className="text-gray-600">Loading settings...</p>
      </div>
    );
  }

  const tabs = [
    { key: 'employees', label: 'Employees' },
    { key: 'projects', label: 'Projects' },
    ...(isAdmin ? [{ key: 'supervisors', label: 'Supervisors' }] : []),
  ] as { key: 'employees' | 'projects' | 'supervisors'; label: string }[];

  return (
    <div>
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      <div className="mb-6 border-b">
        <div className="flex gap-4">
          {tabs.map((t) => (
            <button
              key={t.key}
              onClick={() => setTab(t.key)}
              className={`px-4 py-3 font-medium border-b-2 transition-colors ${
                tab === t.key
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-600 hover:text-gray-900'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* ===================== EMPLOYEES TAB ===================== */}
      {tab === 'employees' && (
        <div className="space-y-6">
          {/* Edit Employee Modal */}
          {editingEmployee && (
            <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
              <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-md">
                <h3 className="text-lg font-bold mb-4">Edit Employee</h3>
                <form onSubmit={handleUpdateEmployee} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                    <input
                      type="text"
                      value={editingEmployee.name}
                      onChange={(e) => setEditingEmployee({ ...editingEmployee, name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Hourly Rate</label>
                    <input
                      type="number"
                      step="0.01"
                      value={editingEmployee.hourly_rate}
                      onChange={(e) => setEditingEmployee({ ...editingEmployee, hourly_rate: parseFloat(e.target.value) || 0 })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Position</label>
                    <input
                      type="text"
                      value={editingEmployee.position || ''}
                      onChange={(e) => setEditingEmployee({ ...editingEmployee, position: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  {isAdmin && (
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Supervisor</label>
                      <select
                        value={editingEmployee.supervisor_id}
                        onChange={(e) => setEditingEmployee({ ...editingEmployee, supervisor_id: parseInt(e.target.value) })}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      >
                        {supervisors.map((s) => (
                          <option key={s.id} value={s.id}>
                            {s.email}{s.name ? ` (${s.name})` : ''}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}
                  <div className="flex gap-3 pt-2">
                    <button
                      type="submit"
                      disabled={saving}
                      className="flex-1 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                    >
                      {saving ? 'Saving...' : 'Save'}
                    </button>
                    <button
                      type="button"
                      onClick={() => setEditingEmployee(null)}
                      className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Add Employee Form */}
            <div className="lg:col-span-1 bg-white rounded-lg shadow p-6">
              <h3 className="text-lg font-bold text-gray-900 mb-4">Add Employee</h3>
              <form onSubmit={handleAddEmployee} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                  <input
                    type="text"
                    value={newEmployee.name}
                    onChange={(e) => setNewEmployee({ ...newEmployee, name: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Hourly Rate</label>
                  <input
                    type="number"
                    step="0.01"
                    value={newEmployee.hourly_rate}
                    onChange={(e) => setNewEmployee({ ...newEmployee, hourly_rate: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    placeholder="$25.00"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Position</label>
                  <input
                    type="text"
                    value={newEmployee.position}
                    onChange={(e) => setNewEmployee({ ...newEmployee, position: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    placeholder="e.g., Carpenter"
                  />
                </div>
                {isAdmin && (
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Supervisor</label>
                    <select
                      value={newEmployee.supervisor_id}
                      onChange={(e) => setNewEmployee({ ...newEmployee, supervisor_id: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    >
                      <option value="">— select supervisor —</option>
                      {supervisors.map((s) => (
                        <option key={s.id} value={s.id}>
                          {s.email}{s.name ? ` (${s.name})` : ''}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
                <button
                  type="submit"
                  disabled={saving}
                  className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                >
                  {saving ? 'Adding...' : 'Add Employee'}
                </button>
              </form>
            </div>

            {/* Employees List */}
            <div className="lg:col-span-2 bg-white rounded-lg shadow overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Name</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Position</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Rate</th>
                    {isAdmin && (
                      <th className="px-6 py-3 text-left font-semibold text-gray-700">Supervisor</th>
                    )}
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {employees.map((emp) => {
                    const sup = supervisors.find((s) => s.id === emp.supervisor_id);
                    return (
                      <tr key={emp.id} className="border-b hover:bg-gray-50">
                        <td className="px-6 py-3 font-medium text-gray-900">{emp.name}</td>
                        <td className="px-6 py-3 text-gray-600">{emp.position || '-'}</td>
                        <td className="px-6 py-3 font-semibold">${emp.hourly_rate.toFixed(2)}</td>
                        {isAdmin && (
                          <td className="px-6 py-3 text-gray-500 text-xs">
                            {sup?.email || `#${emp.supervisor_id}`}
                          </td>
                        )}
                        <td className="px-6 py-3">
                          <div className="flex gap-3">
                            <button
                              onClick={() => setEditingEmployee(emp)}
                              className="text-blue-600 hover:text-blue-700 font-medium text-sm"
                            >
                              Edit
                            </button>
                            <button
                              onClick={() => handleDeleteEmployee(emp.id)}
                              className="text-red-600 hover:text-red-700 font-medium text-sm"
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ===================== PROJECTS TAB ===================== */}
      {tab === 'projects' && (
        <div className="space-y-6">
          {/* Edit Project Modal */}
          {editingProject && (
            <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
              <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-md">
                <h3 className="text-lg font-bold mb-4">Edit Project</h3>
                <form onSubmit={handleUpdateProject} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Project Name</label>
                    <input
                      type="text"
                      value={editingProject.name}
                      onChange={(e) => setEditingProject({ ...editingProject, name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Labor Budget</label>
                    <input
                      type="number"
                      step="100"
                      value={editingProject.labor_budget}
                      onChange={(e) => setEditingProject({ ...editingProject, labor_budget: parseFloat(e.target.value) || 0 })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Overhead %</label>
                    <input
                      type="number"
                      step="0.1"
                      value={editingProject.overhead_percentage}
                      onChange={(e) => setEditingProject({ ...editingProject, overhead_percentage: parseFloat(e.target.value) || 0 })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
                    <select
                      value={editingProject.status}
                      onChange={(e) => setEditingProject({ ...editingProject, status: e.target.value as Project['status'] })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    >
                      <option value="active">Active</option>
                      <option value="completed">Completed</option>
                      <option value="on_hold">On Hold</option>
                    </select>
                  </div>
                  <div className="flex gap-3 pt-2">
                    <button
                      type="submit"
                      disabled={saving}
                      className="flex-1 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                    >
                      {saving ? 'Saving...' : 'Save'}
                    </button>
                    <button
                      type="button"
                      onClick={() => setEditingProject(null)}
                      className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Add Project Form */}
            <div className="lg:col-span-1 bg-white rounded-lg shadow p-6">
              <h3 className="text-lg font-bold text-gray-900 mb-4">Add Project</h3>
              <form onSubmit={handleAddProject} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Project Name</label>
                  <input
                    type="text"
                    value={newProject.name}
                    onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Labor Budget</label>
                  <input
                    type="number"
                    step="100"
                    value={newProject.labor_budget}
                    onChange={(e) => setNewProject({ ...newProject, labor_budget: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    placeholder="$50000"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Overhead %</label>
                  <input
                    type="number"
                    step="0.1"
                    value={newProject.overhead_percentage}
                    onChange={(e) => setNewProject({ ...newProject, overhead_percentage: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                </div>
                <button
                  type="submit"
                  disabled={saving}
                  className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                >
                  {saving ? 'Adding...' : 'Add Project'}
                </button>
              </form>
            </div>

            {/* Projects List */}
            <div className="lg:col-span-2 bg-white rounded-lg shadow overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Name</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Budget</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">OH%</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Status</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {projects.map((proj) => (
                    <tr key={proj.id} className="border-b hover:bg-gray-50">
                      <td className="px-6 py-3 font-medium text-gray-900">{proj.name}</td>
                      <td className="px-6 py-3 font-semibold">${proj.labor_budget.toLocaleString()}</td>
                      <td className="px-6 py-3">{proj.overhead_percentage}%</td>
                      <td className="px-6 py-3 capitalize">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                          proj.status === 'active' ? 'bg-green-100 text-green-700'
                          : proj.status === 'completed' ? 'bg-blue-100 text-blue-700'
                          : 'bg-yellow-100 text-yellow-700'
                        }`}>
                          {proj.status}
                        </span>
                      </td>
                      <td className="px-6 py-3">
                        {isAdmin && (
                          <button
                            onClick={() => setEditingProject(proj)}
                            className="text-blue-600 hover:text-blue-700 font-medium text-sm"
                          >
                            Edit
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ===================== SUPERVISORS TAB ===================== */}
      {tab === 'supervisors' && isAdmin && (
        <div className="space-y-6">
          {/* Edit Supervisor Modal */}
          {editingSupervisor && (
            <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
              <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-md">
                <h3 className="text-lg font-bold mb-4">Edit Supervisor</h3>
                <form onSubmit={handleUpdateSupervisor} className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                    <input
                      type="email"
                      value={editSupForm.email}
                      onChange={(e) => setEditSupForm({ ...editSupForm, email: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                    <input
                      type="text"
                      value={editSupForm.name}
                      onChange={(e) => setEditSupForm({ ...editSupForm, name: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      New Password <span className="text-gray-400 font-normal">(leave blank to keep)</span>
                    </label>
                    <input
                      type="password"
                      value={editSupForm.password}
                      onChange={(e) => setEditSupForm({ ...editSupForm, password: e.target.value })}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                      placeholder="New password"
                    />
                  </div>
                  <div className="flex gap-3 pt-2">
                    <button
                      type="submit"
                      disabled={saving}
                      className="flex-1 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                    >
                      {saving ? 'Saving...' : 'Save'}
                    </button>
                    <button
                      type="button"
                      onClick={() => setEditingSupervisor(null)}
                      className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 rounded-lg font-medium"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Add Supervisor Form */}
            <div className="lg:col-span-1 bg-white rounded-lg shadow p-6">
              <h3 className="text-lg font-bold text-gray-900 mb-4">Add Supervisor</h3>
              <form onSubmit={handleAddSupervisor} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                  <input
                    type="email"
                    value={newSupervisor.email}
                    onChange={(e) => setNewSupervisor({ ...newSupervisor, email: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                  <input
                    type="text"
                    value={newSupervisor.name}
                    onChange={(e) => setNewSupervisor({ ...newSupervisor, name: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    placeholder="Full name"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                  <input
                    type="password"
                    value={newSupervisor.password}
                    onChange={(e) => setNewSupervisor({ ...newSupervisor, password: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  />
                </div>
                <button
                  type="submit"
                  disabled={saving}
                  className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
                >
                  {saving ? 'Adding...' : 'Add Supervisor'}
                </button>
              </form>
            </div>

            {/* Supervisors List */}
            <div className="lg:col-span-2 bg-white rounded-lg shadow overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Email</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Name</th>
                    <th className="px-6 py-3 text-center font-semibold text-gray-700">Employees</th>
                    <th className="px-6 py-3 text-center font-semibold text-gray-700">Status</th>
                    <th className="px-6 py-3 text-left font-semibold text-gray-700">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.map((sup) => (
                    <tr key={sup.id} className="border-b hover:bg-gray-50">
                      <td className={`px-6 py-3 font-medium ${!sup.is_active ? 'text-gray-400' : 'text-gray-900'}`}>
                        {sup.email}
                      </td>
                      <td className="px-6 py-3 text-gray-600">{sup.name || '-'}</td>
                      <td className="px-6 py-3 text-center">{sup.employee_count}</td>
                      <td className="px-6 py-3 text-center">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                          sup.is_active ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                        }`}>
                          {sup.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td className="px-6 py-3">
                        <div className="flex gap-3">
                          <button
                            onClick={() => {
                              setEditingSupervisor(sup);
                              setEditSupForm({ email: sup.email, name: sup.name || '', password: '' });
                            }}
                            className="text-blue-600 hover:text-blue-700 font-medium text-sm"
                          >
                            Edit
                          </button>
                          <button
                            onClick={() => handleToggleSupervisorActive(sup.id)}
                            className={`font-medium text-sm ${
                              sup.is_active ? 'text-red-600 hover:text-red-700' : 'text-green-600 hover:text-green-700'
                            }`}
                          >
                            {sup.is_active ? 'Deactivate' : 'Activate'}
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
